"""Build a compact release record from named qualification artifacts, never invent missing outcomes."""
import base64
import html
import json
from pathlib import Path
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[2]
OUT = Path(__file__).resolve().parent
B = ROOT / 'build/siting-qualification'

def read(name):
    return json.loads((B / name).read_text())

annual = read('annual-validation.json')
final = read('final-annual.json')
autonomy = read('autonomy-validation.json')
performance = read('preview-reference.json')
stress = read('preview-multiple-workloads.json')
publications = read('published-examples.json') + read('published-final.json')
root = ET.parse(B / 'current-pytest.xml').getroot()
counts = {k:sum(int(s.attrib.get(k,0)) for s in root.findall('testsuite')) for k in ('tests','failures','errors','skipped')}
validation = dict(schema_version='sites-release-qualification/1',python=counts,
    original_full_browser=dict(passed=89,skipped=18,artifact='build/siting-qualification/current-browser.txt'),
    latest_targeted='build/siting-qualification/final-targeted.xml',
    renderer='build/siting-qualification/final-node.txt',
    playback='build/siting-qualification/final-playback-browser.txt',
    documentation='docs/sites/review-20260913.md',
    original_annual_study=annual['study_id'],fresh_annual=dict(study_id=final['study_id'],hours=final['checks']['completed_hours'],source=final['checks']['source'],checks=final['checks']['checks'],status=final['checks']['status'],seconds=final['seconds']),
    archived_service_study=dict(study_id=autonomy['study_id'],hours_per_case=72,checks=[c['check'] for c in autonomy['cases']],seconds=autonomy['seconds']),
    preview_reference=performance,preview_extra_load=stress,
    publications=publications,
    interpretation='Execution checks apply to their recorded identities. Final status-visibility and window-display fixes have separate targeted tests. No calibration, annual autonomous reliability, site permission or investment validation is inferred.',
    walkthrough=dict(kind='Agent comprehension and live UI walkthrough; not human user research',artifact='build/siting-qualification/live-walkthrough.txt',checked=['Mechanism versus evidence','Regional point versus parcel','Unquoted costs keep NPV unavailable','Original July period and return navigation','Model learning context does not edit site configuration'],misunderstandings=['An initial calendar displayed raw state JSON: replaced with labelled reserves and trace detail','Local playback hour was confused with the global mission clock: fixed with pose-equivalence regression','Cold preview and concurrent workload contention remain distinct from the passed reference p95 gate'],human_feedback='Not yet collected'))
(OUT / 'validation.json').write_text(json.dumps(validation,indent=2)+'\n')
font=base64.b64encode((ROOT/'assets/fonts/DepartureMono-Regular.woff2').read_bytes()).decode()
e=html.escape
names=['London','Seville','Copenhagen']
rows=''.join(f'<tr><td>{name}</td><td>{c["summary"]["methane_kg"]:,.0f}</td><td>€{c["summary"]["total_eur"]:,.0f}</td><td>{c["completed_hours"]:,}</td></tr>' for name,c in zip(names,annual['cases'],strict=True))
months=annual['cases'][0]['summary']['calendar']; maximum=max(m['methane_kg'] for m in months.values())
bars=''.join(f'<rect x="{i*60+35}" y="{200-150*m["methane_kg"]/maximum:.2f}" width="35" height="{150*m["methane_kg"]/maximum:.2f}"/><text x="{i*60+35}" y="225">{key[-2:]}</text>' for i,(key,m) in enumerate(months.items()))
links=''.join(f'<li><a href="../../runs/sites/reports/{p["publication_id"]}.html">{e(p["title"])}</a></li>' for p in publications)
autrows=''.join(f'<tr><td>{name}</td><td>{c["summary"]["methane_kg"]:,.1f}</td><td>{c["check"]["status"]}</td></tr>' for name,c in zip(['Greedy package','Methane MPC package','Economic MPC package'],autonomy['cases'],strict=True))
page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Sites is connected · Dispatch Lab</title><style>@font-face{{font-family:D;src:url(data:font/woff2;base64,{font})}}*{{box-sizing:border-box}}body{{margin:0;background:#202020;color:#d7b98e;font:13px/1.9 D,monospace}}main{{max-width:1120px;margin:auto;padding:60px 30px 100px}}h1,h2,strong{{color:#ffb752;font-weight:normal}}h1{{font-size:42px;line-height:1.3;max-width:950px}}h2{{margin-top:60px;font-size:24px}}p{{max-width:970px}}a{{color:#ffb752;text-underline-offset:4px}}.flow{{border-block:1px solid #79532b;padding:23px 0;margin:35px 0;word-spacing:10px;color:#ffb752}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:25px}}.grid strong{{display:block;font-size:28px}}.grid small{{display:block;line-height:1.7}}table{{width:100%;border-collapse:collapse}}td,th{{text-align:left;padding:12px 8px;border-bottom:1px solid #635034;font-weight:normal}}.scroll{{overflow:auto}}svg{{width:100%;max-width:800px}}svg rect{{fill:#ffb752}}svg text{{fill:#b7986c;font:11px D}}.note{{border-left:2px solid #ffb752;padding-left:20px}}@media(max-width:650px){{h1{{font-size:30px}}.grid{{grid-template-columns:1fr}}main{{padding:30px 20px}}}}</style><main><p>Dispatch Lab / Implementation and qualification</p><h1>From a site to a plant you can watch, inspect and compare.</h1><p>Sites now connects European source evidence, deployment design, continuous hourly operation and separate project cash scenarios. The operating illustration keeps its original presentation. Sources, assumptions and unresolved requirements stay attached to the result.</p><div class="flow">Explore → Assess → Design → Operate → Compare → Playback</div><div class="grid"><div><strong>{counts['tests']:,}</strong><small>Python regression checks passed at the complete workflow checkpoint</small></div><div><strong>26,280 h</strong><small>Three original annual anchor cases; a fresh London year adds 8,760 hours</small></div><div><strong>{performance['preview_p95_ms']:.0f} ms</strong><small>Preview p95 in the defined 240-hour active-batch reference test</small></div></div><h2>What is available</h2><p>Open Sites in the simulation menu. Search, enter coordinates or draw a polygon; preserve resource and constraint evidence; save a plant, service and supply configuration. A study runs on its frozen model and environment with cancellation and checkpoint resumption. Select a recorded week to see its original actions and return to its study. Repricing creates a separate cash report. Finite sizing searches preserve exclusions and incomplete cases.</p><p>The Model workspace explains the area, resource and cash calculations with editable teaching examples. Source imports, country investigation routes, measured-data calibration, versioned write-ups and hash-checked offline restoration are included.</p><h2>A year is a continuous physical history</h2><p>These three regional anchors used the same illustrative plant, Greedy control, 2025 ERA5 reanalysis and explicitly labelled previous-day persistence. They are not screened parcels. Product acceptance is unmodelled; the numbers below are gross methane and allocated operating-period cost.</p><div class="scroll"><table><tr><th>Anchor</th><th>Methane / kg</th><th>Allocated cost</th><th>Hours</th></tr>{rows}</table></div><p>London's monthly output illustrates why annual solar yield cannot be converted into methane with one constant efficiency:</p><svg viewBox="0 0 780 245" role="img" aria-label="London monthly modelled methane output for 2025">{bars}</svg><p>The fresh annual execution passed {final['checks']['checks']:,} independent numerical checks. Material and electrical balance, thermal transitions, operating boundaries, partition continuity and forecast availability were checked against independent calculations. Saved source identities and original archives are retained.</p><h2>Original forecasts and bounded service behaviour</h2><p>A separate 72-hour Seville example uses archived ECMWF issues, a synthetic persistent capacity fault and the existing illustrative repair/support system. All three packages completed and passed the independent physical checks.</p><div class="scroll"><table><tr><th>Controller package</th><th>Methane / kg</th><th>Independent checks</th></tr>{autrows}</table></div><p class="note">The MPC packages produced less in this bounded example. Their service/recovery policies and finite search budgets are part of the treatment; this is not an isolated proof of controller superiority. Inspect ending stocks, forecast horizons, thermal commitments, work and solver limitations before generalising. Numerical verification does not establish realistic fault rates or repair effectiveness.</p><h2>Real data with explicit boundaries</h2><p>Live-tested inputs include PVGIS reference yields, complete ERA5 years, original ECMWF issues and a Seville WorldCover/GLO-30/Natura extract. Initial forecast gust maxima required a distinct preceding-hour convention; the first incomplete retrieval remains recorded. Public map evidence does not establish land rights, water availability, a CO₂ contract or grid access.</p><p>National flood, utility, parcel, commercial and measurement evidence enters through source-bound imports and country routes. These are not silently represented as automatically connected data feeds. Off-grid operation is executable; grid import/export, DAC, hydrogen sales and certified gas delivery remain separately qualified extensions.</p><h2>Costs without false certainty</h2><p>The cash ledger uses capital and replacement payments separately from allocated ownership and wear. It distinguishes gross production from scenario acceptance, current-period inventories from sales, and original dispatch prices from repricing. Missing commercial quotations keep complete NPV and unit cost unavailable. No-build and conditional price scenarios are explicit.</p><h2>Responsiveness and remaining limits</h2><p>The defined active-batch reference passed at {performance['preview_p95_ms']:.1f} ms preview p95 and {performance['render_p95_ms']:.1f} ms rendering p95. Cold first use was {performance['preview_samples_ms'][0]/1000:.2f} seconds. With additional simultaneous annual/offline qualification jobs, preview p95 rose to {stress['preview_p95_ms']:.1f} ms. Both results are retained; the reference pass does not mean every interaction stays below 200 ms.</p><p>Next engineering work should reduce cold-start and multi-workload contention, qualify longer service-rich historical ensembles, obtain site-specific evidence and use it to tighten the surviving uncertainty ranges. Annual autonomous reliability and commercial deployment remain unvalidated.</p><h2>Open the records</h2><ul>{links}</ul><p><a href="../../docs/sites/implementation.md">Workflow and contracts</a> · <a href="validation.json">Machine-readable qualification record</a> · <a href="README.md">Reproduction instructions and scope</a> · <a href="http://127.0.0.1:7860/">Open Dispatch Lab</a></p></main></html>'''
(OUT/'report.html').write_text(page)
print(OUT/'report.html')
